#if os(iOS)

import UIKit
import DuetTheming

/// The colour values, one entry per `SemanticColor`.
///
/// The switch is exhaustive over the vocabulary, so a token added to the config
/// gets a value in the same generation — the property that makes the vocabulary
/// and the palette one unit rather than two lists kept aligned by hand.
extension MainTheme {
  public typealias _ColorAsset = SemanticColor

  public func colorSet(for asset: _ColorAsset) -> ColorSet {
    switch asset {

    // MARK: Surfaces

    case .surface:
      return ColorSet(.auto(light: tokenColor(0xFFFFFF), dark: tokenColor(0x121212)))
    case .cardSurface:
      return ColorSet(.auto(light: tokenColor(0xF1F1EE), dark: tokenColor(0x262626)))

    // A warm wash rather than a grey: the locked state is a state of the card,
    // and a colour the eye reads before the lock glyph does.
    case .lockedSurface:
      return ColorSet(.auto(light: tokenColor(0xFBF3DC), dark: tokenColor(0x3B3320)))

    // MARK: Labels

    case .labelPrimary:
      return ColorSet(.auto(light: tokenColor(0x1A1A1A), dark: tokenColor(0xEDEDED)))
    case .labelSecondary:
      return ColorSet(.auto(light: tokenColor(0x6A6A6A), dark: tokenColor(0x9C9C9C)))
    case .labelLocked:
      return ColorSet(.auto(light: tokenColor(0x7A5C0A), dark: tokenColor(0xE5C15C)))

    // MARK: Chrome

    // Translucent, so it reads as a tint of whichever surface the card sits on;
    // the high-contrast theme maps it onto the primary label, which makes it a
    // solid line of ink.
    case .cardBorder:
      return ColorSet(.auto(
        light: tokenColor(0x1A1A1A, alpha: 0.12),
        dark: tokenColor(0xEDEDED, alpha: 0.16)))
    }
  }
}

/// One typography entry, in the terms both platforms read: a family, a weight,
/// a size, a line height, tracking as a fraction of the em, the variable-font
/// axes a cut is pinned at, and the Dynamic Type style it scales against.
///
/// The axes are load-bearing. A variable face addressed by weight alone renders
/// at its default optical size — no error, visibly wrong glyphs — so the cut a
/// token names is the family plus the axis values, and the app's resolver reads
/// both.
extension MainTheme {
  public struct FontToken {
    public let family: FontFamilyToken
    public let weight: Int
    public let size: CGFloat
    public let lineHeight: CGFloat
    public let trackingEm: CGFloat
    public let opticalSize: CGFloat?
    public let softness: CGFloat?
    public let width: CGFloat?
    public let textStyle: UIFont.TextStyle
  }

  /// Which of the app's three faces a token is set in. The token names a
  /// family, never a file: font resources are app-owned, and the app's resolver
  /// turns a family and its axes into a registered face.
  public enum FontFamilyToken {
    case serif
    case sans
    case mono
  }
}

/// The type values, one entry per `SemanticFont`.
extension MainTheme {
  public typealias _FontAsset = SemanticFont

  public func fontToken(for asset: _FontAsset) -> FontToken {
    switch asset {

    // MARK: The two card styles

    case .cardTitle:
      return FontToken(
        family: .sans,
        weight: 600,
        size: 17,
        lineHeight: 22,
        trackingEm: 0,
        opticalSize: nil,
        softness: nil,
        width: nil,
        textStyle: .headline)

    case .cardBody:
      return FontToken(
        family: .sans,
        weight: 400,
        size: 15,
        lineHeight: 20,
        trackingEm: 0,
        opticalSize: nil,
        softness: nil,
        width: nil,
        textStyle: .subheadline)
    }
  }
}

/// The literal form the tables above are written in. File-private on purpose:
/// the generated file carries its own colour construction so it needs nothing
/// from the app, and an app-wide hex convenience stays the app's to declare.
private func tokenColor(_ rgb: UInt32, alpha: CGFloat = 1) -> UIColor {
  UIColor(
    red: CGFloat((rgb >> 16) & 0xff) / 255.0,
    green: CGFloat((rgb >> 8) & 0xff) / 255.0,
    blue: CGFloat(rgb & 0xff) / 255.0,
    alpha: alpha)
}

#endif
